namespace Algorithms_Easy;

/// <summary>
/// 1332. Remove Palindromic Subsequences
/// You are given a string s consisting only of letters 'a' and 'b'. In a single step you can remove one palindromic subsequence from s.
/// Return the minimum number of steps to make the given string empty.
/// A string is a subsequence of a given string if it is generated by deleting some characters of a given string without changing its order.
/// Note that a subsequence does not necessarily need to be contiguous.
/// A string is called palindrome if is one that reads the same backward as well as forward.
/// </summary>
public class RemovePalindromicSubsequences
{
    /// <summary>
    /// Standart(Базовое решение) +BestSpeed(Лучшее по скорости). Решение через 2 указателя
    /// 1) Главное правило задачи, есть только 2 символа: a, b - значит максимальное значение 2
    /// 2) Строка s != "" из за чего всегда результат будет равен как минимум 1 шагу
    /// </summary>
    /// <param name="s">"abb"</param>
    /// <returns>2</returns>
    public int RemovePalindromeSub(string s)
    {
        int result = 1; 
        int i = 0;
        int j = s.Length - 1;

        while (i < j)
        {
            if (s[i] != s[j])
            {
                result = 2;
                break;
            }

            i++;
            j--;
        }

        return result;
    }
}